import { PASSWORD, USERS, expect, expectStatus, test } from "../../fixtures";

test("Signing out clears the session cookie", { tag: "@AUTH-06" }, async ({ request }) => {
  // Arrange: sign in as the seeded member; the session cookie is kept in this test's request context
  await expectStatus(
    await request.post("/api/auth/login", { data: { email: USERS.member, password: PASSWORD } }),
    200,
  );

  // Act: sign out
  const response = await request.post("/api/auth/logout");

  // Assert
  expect(response.status(), await response.text()).toBe(204);
  const cookie = response
    .headersArray()
    .find((h) => h.name.toLowerCase() === "set-cookie" && h.value.startsWith("session="));
  expect(cookie, "a Set-Cookie header for the session cookie").toBeDefined();
  const value = cookie!.value.toLowerCase();
  const cleared = value.startsWith('session=""') || value.includes("max-age=0") || value.includes("expires=thu, 01 jan 1970");
  expect(cleared, `session cookie is cleared: ${cookie!.value}`).toBe(true);
});
